const state={route:location.hash.replace('#','')||'dashboard'};
const nav=[
['dashboard','⌂','Dashboard'],['project','▣','Project Workspace'],['tasks','☑','Tasks'],['agents','◉','Agents'],
['artifacts','◇','Artifacts'],['decisions','◆','Decisions'],['approvals','⚠','Approvals'],['schedule','◷','Schedule & Cron'],['events','⚡','Events'],['knowledge','▤','Knowledge & Memory']
];
const badge=(t,c='purple')=>`<span class="badge b-${c}">${t}</span>`;
const progress=(v)=>`<div class="progress"><i style="width:${v}%"></i></div>`;
const item=(title,sub,right='')=>`<div class="list-item"><div class="grow"><b>${title}</b>${sub?`<small>${sub}</small>`:''}</div>${right}</div>`;
const metric=(name,value,delta='')=>`<div class="card kpi"><small>${name}</small><strong>${value}</strong>${delta?`<span class="delta">${delta}</span>`:''}</div>`;
function go(route){state.route=route;history.replaceState({},'',`#${route}`);render()}
function shell(content,title){return `<div class="app"><aside class="sidebar"><div class="brand"><div class="logo">A</div><div><b>AOP</b><small>Agent Organization OS</small></div></div><div class="context"><strong>Project Phoenix</strong><span>● In Progress</span></div><div class="nav"><div class="nav-title">OPERATE</div>${nav.slice(0,4).map(([r,i,l])=>`<a data-route="${r}" class="${state.route===r?'active':''}"><span class="ico">${i}</span><span>${l}</span></a>`).join('')}<div class="nav-title">TRUTH & CONTROL</div>${nav.slice(4,9).map(([r,i,l])=>`<a data-route="${r}" class="${state.route.startsWith(r)?'active':''}"><span class="ico">${i}</span><span>${l}</span></a>`).join('')}<div class="nav-title">KNOWLEDGE</div>${nav.slice(9).map(([r,i,l])=>`<a data-route="${r}" class="${state.route===r?'active':''}"><span class="ico">${i}</span><span>${l}</span></a>`).join('')}</div><div class="profile"><div class="avatar">LD</div><div><b style="font-size:11px">Long Dai</b><small>Founder & CEO</small></div></div></aside><main class="main"><header class="topbar"><div class="crumb">AOP / Phoenix / <b>${title}</b></div><div class="search">⌕ Search organization, work, truth and events…</div><div class="attention" data-route="approvals">${badge('⚠ 7 Attention','amber')}<span>◉</span></div></header>${content}</main></div>`}
function pageHead(title,sub,actions=''){return `<div class="page-head"><div><h1>${title}</h1><p>${sub}</p></div><div class="actions">${actions}</div></div>`}
function tabs(labels,active=0){return `<div class="tabs">${labels.map((x,i)=>`<button class="${i===active?'active':''}">${x}</button>`).join('')}</div>`}
function dashboard(){return shell(`<div class="page">${pageHead('Executive Dashboard','Verified organizational state, human attention and critical work.','<button class="btn">Last 7 days</button><button class="btn primary">Export report</button>')}<div class="grid kpis">${metric('Active Agents','6','+12%')}${metric('Open Tasks','26','+8%')}${metric('Verified Done','42','+18%')}${metric('Success Rate','92.3%','+4.8%')}${metric('Critical Blockers','3','-25%')}${metric('Budget Used','57%','$6.84 / $12.50')}</div><div class="grid two"><section class="card section"><h3>Organization Health</h3><div class="health"><div class="ring"><span>84<small>Healthy</small></span></div><div class="metric-list">${[['Delivery',87],['Agent reliability',89],['Decision quality',78],['Governance',81],['Knowledge coverage',88]].map(([n,v])=>`<div class="metric-row"><span>${n}</span><div class="bar"><i style="width:${v}%"></i></div><b>${v}</b></div>`).join('')}</div></div></section><section class="card section"><h3>Human Attention</h3><div class="list clickable" data-route="approvals">${item('Production deploy approval','Requested by CTO Agent · protected action',badge('High','red'))}${item('Architecture change approval','API gateway routing contract',badge('Review','amber'))}${item('Budget extension','PHX-1402 needs +$4.00',badge('Review','amber'))}</div><div class="list" style="margin-top:8px">${item('API gateway blocker','Blocks authentication workflow',badge('High','red'))}${item('Stale artifact consumer','Frontend references API Spec v3',badge('Impact','purple'))}</div></section></div><div class="grid three" style="margin-top:12px"><section class="card section" style="grid-column:span 2"><h3>Current Initiatives</h3><table class="table"><thead><tr><th>Project</th><th>Owner</th><th>Status</th><th>Verified progress</th><th>Risk</th></tr></thead><tbody><tr data-route="project"><td><b>Project Phoenix</b></td><td>CEO Agent</td><td>${badge('On Track','green')}</td><td>${progress(72)}</td><td>Good</td></tr><tr><td>Context Compiler</td><td>Platform Agent</td><td>${badge('On Track','green')}</td><td>${progress(61)}</td><td>Good</td></tr><tr><td>Runtime PoC</td><td>CTO Agent</td><td>${badge('At Risk','amber')}</td><td>${progress(46)}</td><td>Watch</td></tr></tbody></table></section><section class="card section"><h3>Truth Changes</h3><div class="list">${item('API Specification v4','Artifact approved · 3 consumers',badge('Current','green'))}${item('JWT auth decision','DEC-102 · Active',badge('Active','green'))}${item('Gateway routing','Decision pending',badge('Needs approval','amber'))}</div></section></div></div>`,'Executive Dashboard')}
const tasks={backlog:[['PHX-1410','Define authentication strategy','Backend','High'],['PHX-1411','Onboarding UX flow','Frontend','Medium']],progress:[['PHX-1402','Implement authentication API','Backend','High'],['PHX-1406','Finalize architecture v2','CTO','High']],review:[['PHX-1398','Review auth workflow','QA','High'],['PHX-1399','Dashboard UX review','CEO','Medium']],done:[['PHX-1390','Repository setup','DevOps','Done'],['PHX-1392','API spec v4','Backend','Done']]};
function taskCard(t,p){const [id,name,a,pri]=t;return `<div class="task" ${id==='PHX-1402'?'data-route="task-detail"':''}><div class="meta"><span>${id}</span><span class="grow"></span>${badge(pri,pri==='High'?'red':pri==='Medium'?'amber':pri==='Done'?'green':'blue')}</div><b>${name}</b><div class="meta">◉ ${a} Agent</div>${p!=null?`<div class="mini"><i style="width:${p}%"></i></div>`:''}</div>`}
function project(){return shell(`<div class="page"><section class="card"><div class="project-head"><div><label>PROJECT</label><h2>Project Phoenix</h2><span class="subtle">Build a verified autonomous software-company work loop.</span></div><div><label>Verified progress</label><strong>72%</strong></div><div><label>Agents</label><strong>6 / 9 active</strong></div><div><label>Open tasks</label><strong>26</strong></div><div><label>Health</label><strong style="color:var(--green)">On Track</strong></div></div>${tabs(['Overview','Tasks','Agents','Artifacts','Decisions','Discussion','Timeline'])}</section><div class="grid two" style="margin-top:12px"><section class="card section"><h3>Work Coordination Board</h3><div class="kanban"><div class="column"><h4>Backlog · 8</h4>${tasks.backlog.map(x=>taskCard(x)).join('')}</div><div class="column"><h4>In Progress · 5</h4>${tasks.progress.map((x,i)=>taskCard(x,[78,80][i])).join('')}</div><div class="column"><h4>Review · 3</h4>${tasks.review.map((x,i)=>taskCard(x,[90,60][i])).join('')}</div><div class="column"><h4>Done · 12</h4>${tasks.done.map(x=>taskCard(x)).join('')}</div></div></section><section class="card section"><h3>Collaboration Room</h3><div class="msg"><div class="avatar">CEO</div><div class="bubble"><span class="who">CEO Agent</span><span class="time">10:32</span><br>Finish auth API and clear the gateway blocker today.</div></div><div class="msg"><div class="avatar">CTO</div><div class="bubble"><span class="who">CTO Agent</span><span class="time">10:34</span><br>API Spec v4 is authoritative.<div class="attachment" data-route="artifact-detail">◇ API Specification v4 · Approved artifact</div></div></div><div class="msg"><div class="avatar">BE</div><div class="bubble"><span class="who">Backend Agent</span><span class="time">10:36</span><br>Implementation 78%. Awaiting routing decision.</div></div><div class="list">${item('Critical path','Auth API → Integration tests → Staging',badge('On Track','green'))}${item('Human approval','Deploy auth service to staging',badge('Pending','amber'))}</div></section></div></div>`,'Project Workspace')}
function tasksPage(){return shell(`<div class="page">${pageHead('Tasks','Plan, inspect and verify organizational work.')}<section class="card section"><div class="kanban"><div class="column"><h4>Backlog</h4>${tasks.backlog.map(x=>taskCard(x)).join('')}</div><div class="column"><h4>In Progress</h4>${tasks.progress.map((x,i)=>taskCard(x,[78,80][i])).join('')}</div><div class="column"><h4>Review</h4>${tasks.review.map((x,i)=>taskCard(x,[90,60][i])).join('')}</div><div class="column"><h4>Done</h4>${tasks.done.map(x=>taskCard(x)).join('')}</div></div></section></div>`,'Tasks')}
function taskDetail(){return shell(`<div class="page"><section class="card"><div class="detail-head"><div><label>PHX-1402 · HIGH</label><h2>Implement authentication API</h2><span class="subtle">Work contract owned by Backend Agent.</span></div><div><label>Owner</label><strong data-route="agent-detail">Backend Agent</strong></div><div><label>Reviewer</label><strong>QA Agent</strong></div><div><label>Status</label><strong style="color:#c6b8ff">In Review</strong></div><div><label>Verified</label><strong>78%</strong></div></div><div class="lifecycle"><div class="step done"><span class="dot">✓</span>Proposed</div><div class="step done"><span class="dot">✓</span>Ready</div><div class="step done"><span class="dot">✓</span>Running</div><div class="step active"><span class="dot">4</span>Review</div><div class="step"><span class="dot">5</span>Completed</div></div></section><div class="detail-layout" style="margin-top:12px"><div class="detail-main"><section class="card section"><h3>Acceptance Criteria</h3><div class="check ok">Login returns JWT</div><div class="check ok">Refresh token rotation</div><div class="check ok">bcrypt hashing</div><div class="check ok">Rate limit policy</div><div class="check todo">QA verifies audit logging</div></section><section class="card section"><h3>Authoritative Inputs</h3><div class="list clickable" data-route="artifact-detail">${item('API Specification','artifact_api_spec · v4',badge('Approved','green'))}</div><div class="list clickable" data-route="decision-detail" style="margin-top:7px">${item('JWT Authentication','DEC-102',badge('Active','green'))}</div></section><section class="card section"><h3>Current Run & Lease</h3><div class="kv"><div><span>Run</span>run_9f7a2c3d</div><div><span>Attempt</span>2</div><div><span>Lease</span>23m 45s</div><div><span>Tokens</span>143.6K / 250K</div><div><span>Tools</span>23 / 100</div><div><span>Workspace</span>worktree/auth-api</div></div></section><section class="card section"><h3>Evidence</h3>${item('Automated Test Report','50 passed · artifact_test_report_18',badge('Verified','green'))}${item('Security Review','Security Agent',badge('Approved','green'))}</section><section class="card section wide"><h3>Discussion</h3><div class="msg"><div class="avatar">BE</div><div class="bubble"><span class="who">Backend Agent</span><br>Implementation submitted. Waiting on gateway routing.</div></div><div class="msg"><div class="avatar">QA</div><div class="bubble"><span class="who">QA Agent</span><br>Core flow correct. Final approval waits on dependency.</div></div></section></div><aside class="grid"><section class="card section"><h3>Blocker</h3>${item('PHX-1401 Gateway rules','Hard dependency',badge('High','red'))}</section><section class="card section"><h3>Approval</h3><div data-route="approvals-detail" class="clickable">${item('Deploy to staging','Policy requires human approval',badge('Pending','amber'))}</div></section><section class="card section"><h3>Recent Events</h3><div class="eventline"><div class="event" data-route="event-detail">Task submitted for review</div><div class="event">50 tests passed</div><div class="event">Artifact created</div></div></section></aside></div></div>`,'Task PHX-1402')}
function agentsPage(){return shell(`<div class="page">${pageHead('Agent Directory','Inspect workforce capability, authority, workload and performance.')}<div class="grid kpis">${metric('Active','6')}${metric('Busy','2')}${metric('In Review','1')}${metric('Offline','0')}${metric('Avg Reliability','98.2%')}${metric('Cost Today','$11.20')}</div><section class="card section"><table class="table"><thead><tr><th>Agent</th><th>Role</th><th>Status</th><th>Capabilities</th><th>Workload</th><th>Success</th></tr></thead><tbody><tr data-route="agent-detail"><td><b>Backend Agent</b></td><td>Backend Developer</td><td>${badge('Active','green')}</td><td>API · TS · SQL · Auth</td><td>72%</td><td>96.5%</td></tr><tr><td>QA Agent</td><td>QA Specialist</td><td>${badge('In Review','amber')}</td><td>Tests · Security · E2E</td><td>60%</td><td>98.7%</td></tr><tr><td>CTO Agent</td><td>Technical Executive</td><td>${badge('Active','green')}</td><td>Architecture · Planning</td><td>65%</td><td>95.1%</td></tr></tbody></table></section></div>`,'Agents')}
function agentDetail(){return shell(`<div class="page"><section class="card agent-hero"><div class="agent-avatar">◉</div><div>${badge('● Active','green')}<h2 style="margin:8px 0 3px">Backend Agent</h2><div class="subtle">@backend_agent · Engineering workforce identity</div></div><div><label class="subtle">Role</label><b style="display:block">Backend Developer</b></div><div><label class="subtle">Authority</label><b style="display:block">Level 4</b></div><div><label class="subtle">Success</label><b style="display:block">96.5%</b></div><div><label class="subtle">Availability</label><b style="display:block;color:var(--green)">85%</b></div></section>${tabs(['Overview','Capabilities','Memory','Tools','Work','Activity','Performance','Permissions'])}<div class="detail-layout" style="margin-top:12px"><div class="detail-main"><section class="card section"><h3>Current Assignment</h3><div data-route="task-detail" class="clickable">${item('PHX-1402 · Authentication API','Project Phoenix · Review',badge('78%','purple'))}</div></section><section class="card section"><h3>Capabilities</h3>${[['API Design',98],['TypeScript',94],['PostgreSQL',92],['Authentication',90]].map(([n,v])=>`<div class="skill"><span>${n}</span><div class="bar"><i style="width:${v}%"></i></div><b>${v}</b></div>`).join('')}</section><section class="card section"><h3>Memory Classes</h3>${item('Working Memory','12 active items',badge('Ephemeral','blue'))}${item('Project Memory','Phoenix selective knowledge',badge('Selective','purple'))}${item('Decision Context','3 authoritative references',badge('Linked','green'))}</section><section class="card section"><h3>Tools</h3>${item('Git','Own branch',badge('Connected','green'))}${item('Terminal','Sandbox only',badge('Scoped','green'))}${item('PostgreSQL','Read/query dev',badge('Scoped','blue'))}</section><section class="card section wide"><h3>Permissions & Authority</h3><div class="permit"><div><b style="color:var(--green)">CAN DO</b><p>Commit own branch<br>Run tests<br>Query dev DB</p></div><div><b style="color:var(--amber)">APPROVAL</b><p>Deploy staging<br>Change shared spec<br>Extend budget</p></div><div><b style="color:var(--red)">CANNOT</b><p>Deploy production<br>Delete repo<br>Change billing</p></div></div></section></div><aside class="grid"><section class="card section"><h3>Workload</h3><div class="ring" style="margin:auto;width:100px;height:100px"><span>72<small>Utilization</small></span></div></section><section class="card section"><h3>Performance</h3><div class="kv"><div><span>Reliability</span>99.1%</div><div><span>Review pass</span>94.2%</div><div><span>Throughput</span>23.4/day</div><div><span>Cost/task</span>$1.86</div></div></section></aside></div></div>`,'Agent Detail')}
function artifacts(){return shell(`<div class="page">${pageHead('Artifact Registry','Authoritative outputs, immutable versions, provenance and downstream consumers.','<button class="btn">Lineage view</button><button class="btn primary">Publish Artifact</button>')}<div class="grid kpis">${metric('Artifacts','48')}${metric('Approved','31')}${metric('Draft','9')}${metric('Stale Consumers','3')}${metric('Breaking Changes','1')}${metric('Storage','1.8 GB')}</div><section class="card section"><table class="table"><thead><tr><th>Artifact</th><th>Type</th><th>Current</th><th>Producer</th><th>Consumers</th><th>Impact</th></tr></thead><tbody><tr data-route="artifact-detail"><td><b>API Specification</b><br><span class="subtle">artifact_api_spec</span></td><td>OpenAPI</td><td>${badge('v4 Approved','green')}</td><td>CTO Agent / PHX-1406</td><td>5 tasks</td><td>${badge('1 stale','amber')}</td></tr><tr><td>Architecture v2</td><td>Markdown</td><td>${badge('v2 Approved','green')}</td><td>CTO Agent</td><td>8 tasks</td><td>${badge('Clean','green')}</td></tr><tr><td>DB Schema</td><td>SQL</td><td>${badge('v1.3','green')}</td><td>Backend Agent</td><td>4 tasks</td><td>${badge('Clean','green')}</td></tr><tr><td>Test Report</td><td>Evidence</td><td>${badge('run 18','blue')}</td><td>QA Agent</td><td>PHX-1402</td><td>${badge('Verified','green')}</td></tr></tbody></table></section></div>`,'Artifacts')}
function artifactDetail(){return shell(`<div class="page"><section class="card"><div class="detail-head"><div><label>ARTIFACT · OPENAPI</label><h2>API Specification</h2><span class="subtle">artifact_api_spec · canonical service contract</span></div><div><label>Current</label><strong>v4</strong></div><div><label>Status</label><strong style="color:var(--green)">Approved</strong></div><div><label>Producer</label><strong>CTO Agent</strong></div><div><label>Consumers</label><strong>5 tasks</strong></div></div>${tabs(['Overview','Versions','Lineage','Consumers','Discussion','Events','Raw'])}</section><div class="detail-layout" style="margin-top:12px"><div class="detail-main"><section class="card section"><h3>Version History</h3><div class="timeline-list"><div class="timeline-row current"><b>v4 · Current Approved</b><span>May 24 · SHA 8f2a…</span>${badge('Approved','green')}</div><div class="timeline-row"><b>v3</b><span>May 22 · superseded by v4</span>${badge('Superseded','purple')}</div><div class="timeline-row"><b>v2</b><span>May 20</span>${badge('Superseded','purple')}</div></div></section><section class="card section"><h3>Provenance</h3><div class="kv"><div><span>Produced by task</span><b data-route="task-detail">PHX-1406</b></div><div><span>Producer</span>CTO Agent</div><div><span>Decision</span><b data-route="decision-detail">DEC-114</b></div><div><span>Checksum</span>sha256:8f2a…</div></div></section><section class="card section wide"><h3>Lineage & Impact</h3><div class="lineage"><div class="node">PRD v2</div><span>→</span><div class="node">Architecture v2</div><span>→</span><div class="node active">API Spec v4</div><span>→</span><div class="node warn">Frontend PHX-1411 · stale v3</div></div><div class="impact-note">Breaking route change in v4 affected 3 consumers. Backend rebased; QA updated; Frontend still requires rebase.</div></section><section class="card section wide"><h3>Consumers</h3><table class="table"><tbody><tr data-route="task-detail"><td><b>PHX-1402 Auth API</b></td><td>uses v4</td><td>${badge('Current','green')}</td></tr><tr><td>PHX-1411 Onboarding UI</td><td>uses v3</td><td>${badge('Stale','amber')}</td></tr><tr><td>PHX-1398 Auth Review</td><td>uses v4</td><td>${badge('Current','green')}</td></tr></tbody></table></section></div><aside class="grid"><section class="card section"><h3>Authority</h3>${item('Approval','CTO Agent',badge('Approved','green'))}${item('Schema','OpenAPI 3.1','')}</section><section class="card section"><h3>Related Decision</h3><div data-route="decision-detail" class="clickable">${item('DEC-114 API contract v4','Breaking route update',badge('Active','green'))}</div></section><section class="card section"><h3>Recent Events</h3><div class="eventline"><div class="event" data-route="event-detail">artifact.version.approved</div><div class="event">artifact.consumer.stale</div><div class="event">impact.analysis.completed</div></div></section></aside></div></div>`,'Artifact Detail')}
function decisions(){return shell(`<div class="page">${pageHead('Decision Registry','Authoritative organizational choices and their downstream impact.','<button class="btn primary">New Decision</button>')}<div class="grid kpis">${metric('Active','18')}${metric('Proposed','4')}${metric('Approval Pending','2')}${metric('Superseded','11')}${metric('Rejected','3')}${metric('Avg cycle','18.6h')}</div><section class="card section"><table class="table"><thead><tr><th>Decision</th><th>Scope</th><th>Proposer</th><th>Authority</th><th>Status</th><th>Impact</th></tr></thead><tbody><tr data-route="decision-detail"><td><b>DEC-114 · API Contract v4</b><br><span class="subtle">Change auth route and token response</span></td><td>Engineering</td><td>CTO Agent</td><td>CTO</td><td>${badge('Active','green')}</td><td>3 tasks · 1 stale</td></tr><tr><td>DEC-102 · Use JWT</td><td>Engineering</td><td>Backend Agent</td><td>CTO</td><td>${badge('Active','green')}</td><td>Auth subsystem</td></tr><tr><td>DEC-119 · Staging Deploy</td><td>Production</td><td>CTO Agent</td><td>Human</td><td>${badge('Approval Pending','amber')}</td><td>Protected action</td></tr></tbody></table></section></div>`,'Decisions')}
function decisionDetail(){return shell(`<div class="page"><section class="card"><div class="detail-head"><div><label>DEC-114 · ENGINEERING</label><h2>Approve API Contract v4</h2><span class="subtle">Authoritative decision governing the authentication API contract.</span></div><div><label>Status</label><strong style="color:var(--green)">Active</strong></div><div><label>Proposer</label><strong>CTO Agent</strong></div><div><label>Authority</label><strong>CTO</strong></div><div><label>Effective</label><strong>May 24</strong></div></div>${tabs(['Overview','Options','Impact','Discussion','Events'])}</section><div class="detail-layout" style="margin-top:12px"><div class="detail-main"><section class="card section"><h3>Question</h3><p class="bodycopy">Should authentication endpoints adopt the v4 route naming and explicit refresh-token response contract?</p></section><section class="card section"><h3>Selected Option</h3>${item('Option B · Adopt v4 contract','Cleaner resource naming and explicit token rotation.',badge('Selected','green'))}</section><section class="card section"><h3>Options Considered</h3>${item('Option A · Keep v3','Avoid migration cost',badge('Rejected','red'))}${item('Option B · Adopt v4','Improves contract clarity',badge('Selected','green'))}</section><section class="card section"><h3>Rationale</h3><p class="bodycopy">v4 reduces ambiguity between session creation and token refresh, aligns backend and security requirements, and improves testability. Migration impact is bounded and traceable.</p></section><section class="card section wide"><h3>Downstream Impact</h3><div class="lineage"><div class="node active">DEC-114</div><span>→</span><div class="node" data-route="artifact-detail">API Spec v4</div><span>→</span><div class="node">Backend PHX-1402</div><span>→</span><div class="node warn">Frontend PHX-1411</div></div></section></div><aside class="grid"><section class="card section"><h3>Approval</h3>${item('Approved by','CTO Agent',badge('Authorized','green'))}${item('Policy','Engineering architecture','')}</section><section class="card section"><h3>Affected Objects</h3><div data-route="artifact-detail" class="clickable">${item('API Specification v4','artifact_api_spec',badge('Current','green'))}</div><div data-route="task-detail" class="clickable">${item('PHX-1402 Auth API','uses v4',badge('Current','green'))}</div></section><section class="card section"><h3>Events</h3><div class="eventline"><div class="event" data-route="event-detail">decision.approved</div><div class="event">artifact.version.created</div></div></section></aside></div></div>`,'Decision Detail')}
function approvals(){return shell(`<div class="page">${pageHead('Approval Center','Human intervention queue for actions that exceed agent authority.','<button class="btn">Policy view</button>')}<div class="grid kpis">${metric('Pending','3')}${metric('High Risk','1')}${metric('Overdue','0')}${metric('Approved Today','8')}${metric('Rejected Today','1')}${metric('Median wait','12m')}</div><div class="approval-layout"><section class="card section"><h3>Pending Approvals</h3><div class="approval-row selected" data-route="approvals-detail"><div class="risk-dot high"></div><div class="grow"><b>Deploy authentication service to staging</b><small>CTO Agent · Project Phoenix · requested 8m ago</small></div>${badge('High','red')}</div><div class="approval-row"><div class="risk-dot medium"></div><div class="grow"><b>Approve architecture change</b><small>CTO Agent · API gateway routing</small></div>${badge('Medium','amber')}</div><div class="approval-row"><div class="risk-dot medium"></div><div class="grow"><b>Extend PHX-1402 budget by $4</b><small>Backend Agent · token/tool budget</small></div>${badge('Medium','amber')}</div></section><section class="card section attention-preview"><h3>Selected Request</h3><div class="attention-title"><div><span class="subtle">APPROVAL-028</span><h2>Deploy authentication service to staging</h2></div>${badge('Human Required','amber')}</div><div class="kv"><div><span>Requester</span>CTO Agent</div><div><span>Action</span>production.deploy.staging</div><div><span>Target</span>auth-service:v1.2.3</div><div><span>Policy</span>DEPLOY-004</div><div><span>Estimated cost</span>$2.40</div><div><span>Risk</span>High</div></div><div class="evidence-box"><b>Evidence available</b><p>50 tests passed · Security approved · API Spec v4 current · QA conditional pass.</p></div><div class="actions"><button class="btn">Request changes</button><button class="btn danger">Reject</button><button class="btn primary">Approve</button></div></section></div></div>`,'Approval Center')}
function approvalDetail(){return shell(`<div class="page"><section class="card"><div class="detail-head"><div><label>APPROVAL-028 · PROTECTED ACTION</label><h2>Deploy authentication service to staging</h2><span class="subtle">Requested by CTO Agent because policy DEPLOY-004 requires human authority.</span></div><div><label>Status</label><strong style="color:var(--amber)">Pending</strong></div><div><label>Risk</label><strong>High</strong></div><div><label>Age</label><strong>8m</strong></div><div><label>Project</label><strong>Phoenix</strong></div></div></section><div class="detail-layout" style="margin-top:12px"><div class="detail-main"><section class="card section"><h3>Requested Command</h3><pre class="payload">production.deploy.staging\nactor: CTO Agent\ntarget: auth-service:v1.2.3\nenvironment: staging\nexpected_revision: 18</pre></section><section class="card section"><h3>Why Approval Is Required</h3><p class="bodycopy">The CTO may request a staging deployment, but execution requires human approval when the deployment touches a protected shared environment.</p>${item('Policy rule','DEPLOY-004 · protected_environment',badge('REQUIRE_APPROVAL','amber'))}</section><section class="card section"><h3>Evidence</h3>${item('Test Report','50 / 50 passed',badge('Verified','green'))}${item('Security Review','SEC-201',badge('Approved','green'))}${item('API Specification','v4',badge('Current','green'))}</section><section class="card section"><h3>Impact / Risk</h3><div class="kv"><div><span>Affected service</span>auth-service</div><div><span>Downstream</span>Frontend integration</div><div><span>Rollback</span>Available</div><div><span>Estimated cost</span>$2.40</div></div></section><section class="card section wide"><h3>Human Decision</h3><textarea class="note" placeholder="Optional approval/rejection note"></textarea><div class="actions"><button class="btn">Request changes</button><button class="btn danger">Reject</button><button class="btn primary">Approve command</button></div></section></div><aside class="grid"><section class="card section"><h3>Requester</h3>${item('CTO Agent','Technical Executive',badge('Authorized requester','green'))}</section><section class="card section"><h3>Related</h3><div data-route="task-detail" class="clickable">${item('PHX-1402','Authentication API','')}</div><div data-route="artifact-detail" class="clickable">${item('API Spec v4','Authoritative input','')}</div></section><section class="card section"><h3>Audit</h3><div class="eventline"><div class="event" data-route="event-detail">approval.requested</div><div class="event">policy.require_approval</div></div></section></aside></div></div>`,'Approval Detail')}
function schedule(){return shell(`<div class="page">${pageHead('Schedule & Cron','Recurring agent work, automation, reviews, deployments and milestones.','<button class="btn">Asia/Ho_Chi_Minh</button><button class="btn primary">New Schedule</button>')}<div class="grid kpis">${metric('Scheduled Jobs','14','+2')}${metric('Healthy','12')}${metric('Missed','1')}${metric('Paused','1')}${metric('Next Run','10:30')}${metric('Success 30d','96.3%')}</div><div class="schedule-layout"><section class="card section calendar"><h3>August 2026</h3><div class="calendar-grid">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<b>${d}</b>`).join('')}${Array.from({length:35},(_,i)=>{const d=i-2;return `<div class="day ${d===25?'today':''}"><span>${d>0&&d<32?d:''}</span>${d===25?'<em>10:30 API Sync</em><em>15:00 QA Review</em>':''}${d===27?'<em>09:00 Security Scan</em>':''}${d===29?'<em>18:00 Weekly Report</em>':''}</div>`}).join('')}</div></section><section class="card section"><h3>Upcoming</h3><div class="list"><div data-route="schedule-detail" class="clickable">${item('10:30 · API Sync v2','Data Agent · every weekday',badge('in 23m','green'))}</div>${item('15:00 · QA Review','QA Agent · task review window',badge('Today','blue'))}${item('18:00 · Weekly Report','CEO Agent · Friday',badge('4d','purple'))}${item('09:00 · Security Scan','Security Agent · Tue/Thu',badge('2d','green'))}</div><h3 style="margin-top:18px">Missed / Failed</h3>${item('API Sync v1','Aug 24 · external API timeout',badge('Missed','red'))}</section></div></div>`,'Schedule & Cron')}
function scheduleDetail(){return shell(`<div class="page"><section class="card"><div class="detail-head"><div><label>SCHEDULE · ACTIVE</label><h2>API Sync v2</h2><span class="subtle">Recurring Data Agent job linked to the Phoenix data pipeline.</span></div><div><label>Next Run</label><strong>10:30</strong></div><div><label>Timezone</label><strong>Asia/HCM</strong></div><div><label>Owner</label><strong>Data Agent</strong></div><div><label>Health</label><strong style="color:var(--green)">96.3%</strong></div></div>${tabs(['Overview','Run History','Settings','Raw'])}</section><div class="detail-layout" style="margin-top:12px"><div class="detail-main"><section class="card section"><h3>Human-readable Schedule</h3><div class="schedule-rule"><strong>Every weekday at 10:30 AM</strong><span>Asia/Ho_Chi_Minh (UTC+7)</span></div></section><section class="card section"><h3>Raw Cron</h3><pre class="payload">30 10 * * 1-5</pre></section><section class="card section wide"><h3>Run History</h3><table class="table"><tbody><tr><td>Aug 25 10:30</td><td>${badge('Success','green')}</td><td>2m 08s</td><td>run_sched_128</td></tr><tr><td>Aug 24 10:30</td><td>${badge('Failed','red')}</td><td>43s</td><td>external API timeout</td></tr><tr><td>Aug 23 10:30</td><td>${badge('Success','green')}</td><td>2m 11s</td><td>run_sched_126</td></tr></tbody></table></section><section class="card section"><h3>Execution Policy</h3><div class="kv"><div><span>Retries</span>2</div><div><span>Timeout</span>5m</div><div><span>Concurrency</span>1</div><div><span>Miss handling</span>Alert owner</div></div></section><section class="card section"><h3>Linked Resources</h3>${item('Data Pipeline','PHX-DATA-01','')}${item('External API','Provider connector','')}</section></div><aside class="grid"><section class="card section"><h3>Controls</h3><div class="stack-actions"><button class="btn primary">Run now</button><button class="btn">Pause schedule</button><button class="btn">Edit</button></div></section><section class="card section"><h3>Recent Event</h3><div class="eventline"><div class="event" data-route="event-detail">schedule.run.completed</div><div class="event">schedule.run.failed</div></div></section></aside></div></div>`,'Schedule Detail')}
